#include "../src/audio_effects_buffer.h"
#include <stdio.h>
int main(void){TaxiAudioAsset a={0};if(taxi_audio_asset_load(&a,"outputs/crazy-taxi-native/assets/audio"))return 1;unsigned mask,count,tail,protect,global;while(scanf("%u %u %u %u %u",&mask,&count,&tail,&protect,&global)==5){TaxiAudioChannel c[4]={0};unsigned indices[4]={9,10,58,41};for(unsigned k=0;k<4;k++){c[k].stamp=0xa5a5a5a5+k;c[k].rate=1234;c[k].phase=tail?(a.sounds[indices[k]].length-1)*256+128:0;c[k].step=128+k*64;c[k].volume=(uint8_t)(64+k*7);c[k].last=165;c[k].flags4=(uint8_t)(k==3?1:protect);c[k].flags5=255;if(k!=1)c[k].sound=a.sounds+indices[k];}int16_t mix[352];for(unsigned j=0;j<count;j++)mix[j]=(int16_t)(j*257-30000);uint8_t request=165;if(taxi_audio_effects_buffer(c,&request,mix,count,a.codebook,608,(uint8_t)(mask&1),(uint8_t)(mask&2),(uint8_t)(mask&4),(uint8_t)global))return 1;printf("%u",request);for(unsigned k=0;k<4;k++)printf(" %u %u %u %u %u %u %u %u %u",c[k].stamp,c[k].rate,c[k].phase,c[k].step,c[k].flags4,c[k].flags5,c[k].volume,c[k].last,c[k].sound!=0);for(unsigned j=0;j<count;j++)printf(" %d",mix[j]);putchar('\n');}taxi_audio_asset_free(&a);return 0;}
